-- ============================================================================
-- Importacao da base de clientes do Bling
-- Gerado em 2026-05-18 a partir de 2 exports do Bling:
--   Base de dados clientes Bling/contatos_2026-05-19-01-37-06.csv (501 linhas)
--   Base de dados clientes Bling/contatos_2026-05-19-01-37-30.csv (429 linhas)
--
-- Filtros aplicados:
--   * Tipo contato contem 'Cliente' (descarta Fornecedor, Funcionario, sem categoria)
--   * Nome nao vazio e diferente de 'Consumidor Final'
--   * Dedupe por telefone (digitos) com fallback pra nome normalizado
--
-- Mapeamento Bling -> cliente (schema REAL: sem cidade/uf/cep separados):
--   Nome              -> nome
--   Celular || Fone   -> telefone (Celular tem prioridade)
--   Endereco+Numero+Complemento+Bairro + Cidade/UF + CEP -> endereco (concat)
--   E-mail            -> email
--   Observacoes + CPF/CNPJ + Bling ID -> observacoes (com separador '|')
--
-- IDEMPOTENTE: roda quantas vezes quiser, so insere os que nao existem
-- (match por telefone normalizado OU nome lowercased).
--
-- Total na importacao: 777 clientes unicos.
--
-- v3 (2026-05-19): alinhado ao schema real da tabela `cliente`.
--   - fone -> telefone
--   - obs  -> observacoes
--   - cidade/uf/cep NAO existem como colunas separadas; concatenados no endereco
-- ============================================================================

BEGIN;

-- 1) Staging temp table
CREATE TEMP TABLE cliente_bling_stg (
  nome      text NOT NULL,
  fone      text,
  fone_norm text,
  endereco  text,
  cidade    text,
  uf        text,
  cep       text,
  email     text,
  obs       text
) ON COMMIT DROP;

