-- 3) Insere SO os que nao existem ja no banco
--    Match: por telefone normalizado (digitos) quando staging tem fone
--           ou por nome lowercased quando staging nao tem fone
--    Endereco final = endereco_bling — cidade/uf — cep (parts existentes,
--    juntadas com ' — '). Replica a logica de criarClientePersist no front.
SELECT
  s.nome,
  NULLIF(s.fone, ''),
  NULLIF(
    array_to_string(
      ARRAY(
        SELECT x FROM (VALUES
          (NULLIF(s.endereco, '')),
          (NULLIF(concat_ws('/', NULLIF(s.cidade,''), NULLIF(s.uf,'')), '')),
          (NULLIF(s.cep, ''))
        ) AS t(x)
        WHERE x IS NOT NULL
      ),
      ' — '
    ),
    ''
  ),
  NULLIF(s.email, ''),
  NULLIF(s.obs, '')
FROM cliente_bling_stg s
WHERE NOT EXISTS (
  SELECT 1 FROM cliente c
  WHERE c.deleted_at IS NULL
    AND (
      (LENGTH(COALESCE(s.fone_norm,'')) >= 8 AND regexp_replace(COALESCE(c.telefone,''), '\D', '', 'g') = s.fone_norm)
      OR
      (LENGTH(COALESCE(s.fone_norm,'')) <  8 AND lower(trim(c.nome)) = lower(trim(s.nome)))
    )
);

-- 4) Relatorio: quantos foram inseridos
DO $$
DECLARE
  v_total_staging int;
  v_total_cliente int;
BEGIN
  SELECT COUNT(*) INTO v_total_staging FROM cliente_bling_stg;
  SELECT COUNT(*) INTO v_total_cliente FROM cliente WHERE deleted_at IS NULL;
  RAISE NOTICE 'Linhas na staging: %', v_total_staging;
  RAISE NOTICE 'Total ativos em cliente apos import: %', v_total_cliente;
END $$;

COMMIT;

